const input = $input.first().json || {};

const allowed = new Set([
  // CRM
  'gtm_contact_crm_sync_plan_v1',
  'gtm_contact_crm_sync_tasks_v1',
  'gtm_claim_contact_crm_sync_v1',
  'gtm_finalize_contact_crm_sync_v1',
  'gtm_seed_contact_crm_sync_run_v1',

  // Contact acquisition V1.1
  'gtm_contact_company_discovery_plan_v1',
  'gtm_seed_contact_company_discovery_run_v1',
  'gtm_claim_contact_provider_search_v1',
  'gtm_finish_contact_provider_search_v1',
  'gtm_ingest_contact_provider_results_v1',

  // Contact readiness / enrichment
  'gtm_contact_outbound_ready_plan_v1',
  'gtm_contact_email_enrichment_plan_v1',
  'gtm_seed_contact_email_enrichment_run_v1',
  'gtm_claim_contact_email_enrichment_v1',
  'gtm_finalize_contact_email_enrichment_v1',

  // Outreach planning / execution ledger
  'gtm_email_outreach_plan_v1',
  'gtm_email_sequence_plan_v1',
  'gtm_seed_email_outreach_run_v1',
  'gtm_outreach_tasks_v1',
  'gtm_claim_outreach_task_v1',
  'gtm_finalize_outreach_task_v1',

  // Message layer
  'gtm_render_outreach_message_v1',
  'gtm_set_outreach_message_approval_v1',

  // Provider boundary
  'gtm_outreach_dispatch_plan_v1',
  'gtm_set_outreach_provider_live_v1',

  // Delivery / reply lifecycle
  'gtm_ingest_outreach_provider_event_v1',
  'gtm_record_outreach_reply_v1',

  // Reporting / QA
  'gtm_project01_funnel_report_v1',
  'gtm_project01_contact_state_report_v1',
  'gtm_project01_qa_report_v1'
]);

const rpc = String(input.rpc_name || '').trim();

if (!allowed.has(rpc)) {
  throw new Error(`Supabase broker V3 rejected RPC: ${rpc}`);
}

const body = input.rpc_body ?? {};

if (typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Supabase broker V3 rpc_body must be a JSON object');
}

return [{
  json: {
    broker_version: 'SB-BROKER-V3.0.0',
    rpc_name: rpc,
    url: `https://YOUR_PROJECT.supabase.co/rest/v1/rpc/${rpc}`,
    body
  }
}];

const req = $('Validate and Route Supabase RPC').first().json;

const items = $input.all();
const raw = items.map(item => item.json);

// With "Always Output Data" enabled on the HTTP node, an RPC that
// legitimately returns [] is represented by one synthetic empty item.
// Convert that back into the provider-neutral response: [] contract.
const syntheticEmpty =
  raw.length === 1 &&
  raw[0] &&
  typeof raw[0] === 'object' &&
  !Array.isArray(raw[0]) &&
  Object.keys(raw[0]).length === 0;

const response = syntheticEmpty
  ? []
  : raw.flatMap(value =>
      Array.isArray(value) ? value : [value]
    );

return [{
  json: {
    broker: 'supabase',
    broker_version: req.broker_version,
    rpc_name: req.rpc_name,
    response
  }
}];
